import { screen, within } from "@testing-library/react";
import type ReactMarkdown from "react-markdown";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { SkillMarkdown } from "./SkillMarkdown";
import type { ReferenceIndex } from "./references";

// Scoped to this file: lets the error-boundary test force a render failure
// while every other case still exercises the real react-markdown.
vi.mock("react-markdown", async (importOriginal) => {
  const actual = await importOriginal<{ default: typeof ReactMarkdown }>();
  const OriginalMarkdown = actual.default;
  const MaybeThrowingMarkdown: typeof OriginalMarkdown = (props) => {
    if (typeof props.children === "string" && props.children.includes("__FORCE_MARKDOWN_ERROR__")) {
      throw new Error("forced markdown render failure");
    }
    return <OriginalMarkdown {...props} />;
  };
  return { ...actual, default: MaybeThrowingMarkdown };
});

const references: ReferenceIndex = new Map([
  ["lock_card", { kind: "tool", target: "lock_card" }],
  ["main", { kind: "block", target: "card_replace__main" }],
]);

describe("SkillMarkdown", () => {
  it("highlights references inside nested list items", () => {
    renderWithProviders(<SkillMarkdown text="- use lock_card and main" references={references} />);

    const listItem = screen.getByRole("listitem");
    expect(within(listItem).getByTestId("skill-reference-tool")).toHaveTextContent("lock_card");
    expect(within(listItem).getByTestId("skill-reference-block")).toHaveTextContent("main");
  });

  it("renders inline code as a reference pill when it names a known reference", () => {
    renderWithProviders(<SkillMarkdown text="Call `lock_card` first." references={references} />);

    expect(screen.getByTestId("skill-reference-tool")).toHaveTextContent("lock_card");
  });

  it("does not tokenize references inside fenced code blocks", () => {
    renderWithProviders(<SkillMarkdown text={"```\nlock_card\n```"} references={references} />);

    expect(screen.getByText("lock_card")).toBeInTheDocument();
    expect(screen.queryByTestId("skill-reference-tool")).not.toBeInTheDocument();
  });

  it("falls back to raw text when markdown rendering throws", () => {
    vi.spyOn(console, "error").mockImplementation(vi.fn());
    const text = "Raw prose __FORCE_MARKDOWN_ERROR__ survives.";

    renderWithProviders(<SkillMarkdown text={text} references={references} />);

    expect(screen.getByText(text)).toBeInTheDocument();
  });
});
